156	/**
157	 * WebSocket handshake using pre-read buffer.
158	 */
159	static int do_ws_handshake_ex(int fd, const char* buf, int buf_len,
160	    char* chat_id_out, size_t chat_id_size)
161	{
162	
163	    /* Extract Sec-WebSocket-Key */
164	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
165	    if (!key_hdr) {
166	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
167	        return -1;
168	    }
169	    key_hdr += 21;
170	    char* eol = strstr(key_hdr, "\r\n");
171	    if (!eol)
172	        return -1;
173	
174	    char ws_key[128] = { 0 };
175	    size_t klen = (size_t)(eol - key_hdr);
176	    if (klen >= sizeof(ws_key))
177	        return -1;
178	    memcpy(ws_key, key_hdr, klen);
179	    ws_key[klen] = '\0';
180	
181	    /* Compute accept */
182	    char accept[64] = { 0 };
183	    if (make_accept_key(ws_key, accept, sizeof(accept)) < 0)
184	        return -1;
185	
186	    /* Send 101 */
187	    char resp[512];
188	    int rlen = snprintf(resp, sizeof(resp),
189	        "HTTP/1.1 101 Switching Protocols\r\n"
190	        "Upgrade: websocket\r\n"
191	        "Connection: Upgrade\r\n"
192	        "Sec-WebSocket-Accept: %s\r\n\r\n",
193	        accept);
194	    if (send(fd, resp, rlen, 0) != rlen)
195	        return -1;
196	
197	    /* Default chat_id from fd (may be overridden by first message) */
198	    snprintf(chat_id_out, chat_id_size, "ws_%d", fd);
199	    return 0;
200	}
