42	static int mkdirs(const char *path)
43	{
44	    char tmp[256];
45	    snprintf(tmp, sizeof(tmp), "%s", path);
46	    for (char *p = tmp + 1; *p; p++) {
47	        if (*p == '/') {
48	            *p = '\0';
49	            mkdir(tmp, 0700);
50	            *p = '/';
51	        }
52	    }
53	    mkdir(tmp, 0700);
54	    return OK;
55	}
