57	static cJSON *load_json(void)
58	{
59	    FILE *f = fopen(AGENT_CONFIG_FILE, "r");
60	    if (!f) return cJSON_CreateObject();
61	
62	    fseek(f, 0, SEEK_END);
63	    long sz = ftell(f);
64	    fseek(f, 0, SEEK_SET);
65	
66	    if (sz <= 0) { fclose(f); return cJSON_CreateObject(); }
67	
68	    char *buf = (char *)malloc((size_t)(sz + 1));
69	    if (!buf) { fclose(f); return cJSON_CreateObject(); }
70	
71	    size_t n = fread(buf, 1, (size_t)sz, f);
72	    buf[n] = '\0';
73	    fclose(f);
74	
75	    cJSON *root = cJSON_Parse(buf);
76	    free(buf);
77	    return root ? root : cJSON_CreateObject();
78	}
79	
80	static int save_json(cJSON *root)
81	{
82	    char *str = cJSON_PrintUnformatted(root);
83	    if (!str) return ERROR;
84	
85	    /* Use open() with explicit 0600 to ensure config file is owner-only.
86	     * fopen("w") inherits umask which may be too permissive. */
87	    int fd = open(AGENT_CONFIG_FILE,
88	                  O_WRONLY | O_CREAT | O_TRUNC, 0600);
89	    if (fd < 0) { free(str); return ERROR; }
90	
91	    FILE *f = fdopen(fd, "w");
92	    if (!f) { close(fd); free(str); return ERROR; }
93	    fputs(str, f);
94	    fclose(f);
95	    free(str);
96	    return OK;
97	}
