111	int claw_config_get(const char *key, char *buf, size_t buf_size)
112	{
113	    pthread_mutex_lock(&s_lock);
114	    cJSON *root = load_json();
115	    cJSON *item = cJSON_GetObjectItem(root, key);
116	    int ret = ERROR;
117	    if (item && cJSON_IsString(item) && item->valuestring[0] != '\0') {
118	        strncpy(buf, item->valuestring, buf_size - 1);
119	        buf[buf_size - 1] = '\0';
120	        ret = OK;
121	    }
122	    cJSON_Delete(root);
123	    pthread_mutex_unlock(&s_lock);
124	    return ret;
125	}
