127	int claw_config_set(const char *key, const char *value)
128	{
129	    pthread_mutex_lock(&s_lock);
130	    cJSON *root = load_json();
131	    cJSON_DeleteItemFromObject(root, key);
132	    cJSON_AddStringToObject(root, key, value);
133	    int ret = save_json(root);
134	    cJSON_Delete(root);
135	    pthread_mutex_unlock(&s_lock);
136	    return ret;
137	}
