139	int config_del(const char *key)
140	{
141	    pthread_mutex_lock(&s_lock);
142	    cJSON *root = load_json();
143	    cJSON_DeleteItemFromObject(root, key);
144	    int ret = save_json(root);
145	    cJSON_Delete(root);
146	    pthread_mutex_unlock(&s_lock);
147	    return ret;
148	}
